void print_main_help() {
    std::cout << "bedtools is a powerful toolset for genome arithmetic." << std::endl << std::endl;
    std::cout << "Version:   b2e3657" << std::endl;
    std::cout << "About:     developed in the quinlanlab.org and by many contributors worldwide." << std::endl;
    std::cout << "Docs:      http://bedtools.readthedocs.io/" << std::endl;
    std::cout << "Code:      https://github.com/arq5x/bedtools2" << std::endl;
    std::cout << "Mail:      https://groups.google.com/forum/#!forum/bedtools-discuss" << std::endl << std::endl;
    std::cout << "Usage:     bedtools <subcommand> [options]" << std::endl << std::endl;
    std::cout << "The bedtools sub-commands include:" << std::endl << std::endl;
    std::cout << "[ Genome arithmetic ]" << std::endl;
    std::cout << "    intersect     Find overlapping intervals in various ways." << std::endl;
    std::cout << "    window        Find overlapping intervals within a window around an interval." << std::endl;
    std::cout << "    closest       Find the closest, potentially non-overlapping interval." << std::endl;
    std::cout << "    coverage      Compute the coverage over defined intervals." << std::endl;
    std::cout << "    map           Apply a function to a column for each overlapping interval." << std::endl;
    std::cout << "    genomecov     Compute the coverage over an entire genome." << std::endl;
    std::cout << "    merge         Combine overlapping/nearby intervals into a single interval." << std::endl;
    std::cout << "    cluster       Cluster (but don't merge) overlapping/nearby intervals." << std::endl;
    std::cout << "    complement    Extract intervals _not_ represented by an interval file." << std::endl;
    std::cout << "    shift         Adjust the position of intervals." << std::endl;
    std::cout << "    subtract      Remove intervals based on overlaps b/w two files." << std::endl;
    std::cout << "    slop          Adjust the size of intervals." << std::endl;
    std::cout << "    flank         Create new intervals from the flanks of existing intervals." << std::endl;
    std::cout << "    sort          Order the intervals in a file." << std::endl;
    std::cout << "    random        Generate random intervals in a genome." << std::endl;
    std::cout << "    shuffle       Randomly redistribute intervals in a genome." << std::endl;
    std::cout << "    sample        Sample random records from file using reservoir sampling." << std::endl;
    std::cout << "    spacing       Report the gap lengths between intervals in a file." << std::endl;
    std::cout << "    annotate      Annotate coverage of features from multiple files." << std::endl << std::endl;
    std::cout << "[ Multi-way file comparisons ]" << std::endl;
    std::cout << "    multiinter    Identifies common intervals among multiple interval files." << std::endl;
    std::cout << "    unionbedg     Combines coverage intervals from multiple BEDGRAPH files." << std::endl << std::endl;
    std::cout << "[ Paired-end manipulation ]" << std::endl;
    std::cout << "    pairtobed     Find pairs that overlap intervals in various ways." << std::endl;
    std::cout << "    pairtopair    Find pairs that overlap other pairs in various ways." << std::endl << std::endl;
    std::cout << "[ Format conversion ]" << std::endl;
    std::cout << "    bamtobed      Convert BAM alignments to BED (& other) formats." << std::endl;
    std::cout << "    bedtobam      Convert intervals to BAM records." << std::endl;
    std::cout << "    bamtofastq    Convert BAM records to FASTQ records." << std::endl;
    std::cout << "    bedpetobam    Convert BEDPE intervals to BAM records." << std::endl;
    std::cout << "    bed12tobed6   Breaks BED12 intervals into discrete BED6 intervals." << std::endl << std::endl;
    std::cout << "[ Fasta manipulation ]" << std::endl;
    std::cout << "    getfasta      Use intervals to extract sequences from a FASTA file." << std::endl;
    std::cout << "    maskfasta     Use intervals to mask sequences from a FASTA file." << std::endl;
    std::cout << "    nuc           Profile the nucleotide content of intervals in a FASTA file." << std::endl << std::endl;
    std::cout << "[ BAM focused tools ]" << std::endl;
    std::cout << "    multicov      Counts coverage from multiple BAMs at specific intervals." << std::endl;
    std::cout << "    tag           Tag BAM alignments based on overlaps with interval files." << std::endl << std::endl;
    std::cout << "[ Statistical relationships ]" << std::endl;
    std::cout << "    jaccard       Calculate the Jaccard statistic b/w two sets of intervals." << std::endl;
    std::cout << "    reldist       Calculate the distribution of relative distances b/w two files." << std::endl;
    std::cout << "    fisher        Calculate Fisher statistic b/w two feature files." << std::endl << std::endl;
    std::cout << "[ Miscellaneous tools ]" << std::endl;
    std::cout << "    overlap       Computes the amount of overlap from two intervals." << std::endl;
    std::cout << "    igv           Create an IGV snapshot batch script." << std::endl;
    std::cout << "    links         Create a HTML page of links to UCSC locations." << std::endl;
    std::cout << "    makewindows   Make interval \"windows\" across a genome." << std::endl;
    std::cout << "    groupby       Group by common cols. & summarize oth. cols. (~ SQL \"groupBy\")" << std::endl;
    std::cout << "    expand        Replicate lines based on lists of values in columns." << std::endl;
    std::cout << "    split         Split a file into multiple files with equal records or base pairs." << std::endl;
    std::cout << "    summary       Statistical summary of intervals in a file." << std::endl << std::endl;
    std::cout << "[ General Parameters ]" << std::endl;
    std::cout << "     --cram-ref    Reference used by a CRAM input" << std::endl << std::endl;
    std::cout << "[ General help ]" << std::endl;
    std::cout << "    --help        Print this help menu." << std::endl;
    std::cout << "    --version     What version of bedtools are you using?." << std::endl;
    std::cout << "    --contact     Feature requests, bugs, mailing lists, etc." << std::endl << std::endl;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        print_main_help();
        return 0;
    }
    std::string cmd = argv[1];
    if (cmd == "--help" || cmd == "-h") {
        print_main_help();
        return 0;
    }
    if (cmd == "--version") {
        std::cout << "bedtools b2e3657" << std::endl;
        return 0;
    }
    if (cmd == "intersect") {
        // ... I'll implement this later
    } else {
        std::cerr << "error: unrecognized command: " << cmd << std::endl << std::endl;
        return 1;
    }
    return 0;
}
