{"command":"cat <<'EOF' > bedtools_help.h
#include <string>
#include <iostream>

void print_intersect_help() {
    std::cout << std::endl;
    std::cout << "Tool:    bedtools intersect (aka intersectBed)" << std::endl;
    std::cout << "Version: b2e3657" << std::endl;
    std::cout << "Summary: Report overlaps between two feature files." << std::endl;
    std::cout << std::endl;
    std::cout << "Usage:   bedtools intersect [OPTIONS] -a <bed/gff/vcf/bam> -b <bed/gff/vcf/bam>" << std::endl;
    std::cout << std::endl;
    std::cout << "	Note: -b may be followed with multiple databases and/or " << std::endl;
    std::cout << "	wildcard (*) character(s). " << std::endl;
    std::cout << "Options: " << std::endl;
    std::cout << "	-wa	Write the original entry in A for each overlap." << std::endl;
    std::cout << std::endl;
    std::cout << "	-wb	Write the original entry in B for each overlap." << std::endl;
    std::cout << "		- Useful for knowing _what_ A overlaps. Restricted by -f and -r." << std::endl;
    std::cout << std::endl;
    std::cout << "	-loj	Perform a \"left outer join\". That is, for each feature in A" << std::endl;
    std::cout << "		report each overlap with B.  If no overlaps are found, " << std::endl;
    std::cout << "		report a NULL feature for B." << std::endl;
    std::cout << std::endl;
    std::cout << "	-wo	Write the original A and B entries plus the number of base" << std::endl;
    std::cout << "		pairs of overlap between the two features." << std::endl;
    std::cout << "		- Overlaps restricted by -f and -r." << std::endl;
    std::cout << "		  Only A features with overlap are reported." << std::endl;
    std::cout << std::endl;
    std::cout << "	-wao	Write the original A and B entries plus the number of base" << std::endl;
    std::cout << "		pairs of overlap between the two features." << std::endl;
    std::cout << "		- Overlapping features restricted by -f and -r." << std::endl;
    std::cout << "		  However, A features w/o overlap are also reported" << std::endl;
    std::cout << "		  with a NULL B feature and overlap = 0." << std::endl;
    std::cout << std::endl;
    std::cout << "	-u	Write the original A entry _once_ if _any_ overlaps found in B." << std::endl;
    std::cout << "		- In other words, just report the fact >=1 hit was found." << std::endl;
    std::cout << "		- Overlaps restricted by -f and -r." << std::endl;
    std::cout << std::endl;
    std::cout << "	-c	For each entry in A, report the number of overlaps with B." << std::endl;
    std::cout << "		- Reports 0 for A entries that have no overlap with B." << std::endl;
    std::cout << "		- Overlaps restricted by -f, -F, -r, and -s." << std::endl;
    std::cout << std::endl;
    std::cout << "	-C	For each entry in A, separately report the number of" << std::endl;
    std::cout << "		- overlaps with each B file on a distinct line." << std::endl;
    std::cout << "		- Reports 0 for A entries that have no overlap with B." << std::endl;
    std::cout << "		- Overlaps restricted by -f, -F, -r, and -s." << std::endl;
    std::cout << std::endl;
    std::cout << "	-v	Only report those entries in A that have _no overlaps_ with B." << std::endl;
    std::cout << "		- Similar to \"grep -v\" (an homage)." << std::endl;
    std::cout << std::endl;
    std::cout << "	-ubam	Write uncompressed BAM output. Default writes compressed BAM." << std::endl;
    std::cout << std::endl;
    std::cout << "	-s	Require same strandedness.  That is, only report hits in B" << std::endl;
    std::cout << "		that overlap A on the _same_ strand." << std::endl;
    std::cout << "		- By default, overlaps are reported without respect to strand." << std::endl;
    std::cout << std::endl;
    std::cout << "	-S	Require different strandedness.  That is, only report hits in B" << std::endl;
    std::cout << "		that overlap A on the _opposite_ strand." << std::endl;
    std::cout << "		- By default, overlaps are reported without respect to strand." << std::endl;
    std::cout << std::endl;
    std::cout << "	-f	Minimum overlap required as a fraction of A." << std::endl;
    std::cout << "		- Default is 1E-9 (i.e., 1bp)." << std::endl;
    std::cout << "		- FLOAT (e.g. 0.50)" << std::endl;
    std::cout << std::endl;
    std::cout << "	-F	Minimum overlap required as a fraction of B." << std::endl;
    std::cout << "		- Default is 1E-9 (i.e., 1bp)." << std::endl;
    std::cout << "		- FLOAT (e.g. 0.50)" << std::endl;
    std::cout << std::endl;
    std::cout << "	-r	Require that the fraction overlap be reciprocal for A AND B." << std::endl;
    std::cout << "		- In other words, if -f is 0.90 and -r is used, this requires" << std::endl;
    std::cout << "		  that B overlap 90% of A and A _also_ overlaps 90% of B." << std::endl;
    std::cout << std::endl;
    std::cout << "	-e	Require that the minimum fraction be satisfied for A OR B." << std::endl;
    std::cout << "		- In other words, if -e is used with -f 0.90 and -F 0.10 this requires" << std::endl;
    std::cout << "		  that either 90% of A is covered OR 10% of  B is covered." << std::endl;
    std::cout << "		  Without -e, both fractions would have to be satisfied." << std::endl;
    std::cout << std::endl;
    std::cout << "	-split	Treat \"split\" BAM or BED12 entries as distinct BED intervals." << std::endl;
    std::cout << std::endl;
    std::cout << "	-g	Provide a genome file to enforce consistent chromosome sort order" << std::endl;
    std::cout << "		across input files. Only applies when used with -sorted option." << std::endl;
    std::cout << std::endl;
    std::cout << "	-nonamecheck	For sorted data, don't throw an error if the file has different naming conventions" << std::endl;
    std::cout << "			for the same chromosome. ex. \"chr1\" vs \"chr01\"." << std::endl;
    std::cout << std::endl;
    std::cout << "	-sorted	Use the \"chromsweep\" algorithm for sorted (-k1,1 -k2,2n) input." << std::endl;
    std::cout << std::endl;
