    cout << "		- Useful for knowing _what_ A overlaps. Restricted by -f and -r." << endl << endl;
    cout << "	-loj	Perform a \"left outer join\". That is, for each feature in A" << endl;
    cout << "		report each overlap with B.  If no overlaps are found, " << endl;
    cout << "		report a NULL feature for B." << endl << endl;
    cout << "	-wo	Write the original A and B entries plus the number of base" << endl;
