    cout << "		- Overlaps restricted by -f and -r." << endl;
    cout << "		  Only A features with overlap are reported." << endl << endl;
    cout << "	-wao	Write the original A and B entries plus the number of base" << endl;
    cout << "		pairs of overlap between the two features." << endl;
    cout << "		- Overlapping features restricted by -f and -r." << endl;
    cout << "		  However, A features w/o overlap are also reported" << endl;
    cout << "		  with a NULL B feature and overlap = 0." << endl << endl;
    cout << "	-u	Write the original A entry _once_ if _any_ overlaps found in B." << endl;
    cout << "		- In other words, just report the fact >=1 hit was found." << endl;
    cout << "		- Overlaps restricted by -f and -r." << endl << endl;
    cout << "	-c	For each entry in A, report the number of overlaps with B." << endl;
    cout << "		- Reports 0 for A entries that have no overlap with B." << endl;
    cout << "		- Overlaps restricted by -f, -F, -r, and -s." << endl << endl;
    cout << "	-C	For each entry in A, separately report the number of" << endl;
    cout << "		- overlaps with each B file on a distinct line." << endl;
    cout << "		- Reports 0 for A entries that have no overlap with B." << endl;
    cout << "		- Overlaps restricted by -f, -F, -r, and -s." << endl << endl;
    cout << "	-v	Only report those entries in A that have _no overlaps_ with B." << endl;
