    cout << "		that overlap A on the _same_ strand." << endl;
    cout << "		- By default, overlaps are reported without respect to strand." << endl << endl;
    cout << "	-S	Require different strandedness.  That is, only report hits in B" << endl;
    cout << "		that overlap A on the _opposite_ strand." << endl;
    cout << "		- By default, overlaps are reported without respect to strand." << endl << endl;
    cout << "	-f	Minimum overlap required as a fraction of A." << endl;
    cout << "		- Default is 1E-9 (i.e., 1bp)." << endl;
    cout << "		- FLOAT (e.g. 0.50)" << endl << endl;
    cout << "	-F	Minimum overlap required as a fraction of B." << endl;
    cout << "		- Default is 1E-9 (i.e., 1bp)." << endl;
    cout << "		- FLOAT (e.g. 0.50)" << endl << endl;
    cout << "	-r	Require that the fraction overlap be reciprocal for A AND B." << endl;
    cout << "		- In other words, if -f is 0.90 and -r is used, this requires" << endl;
    cout << "		  that B overlap 90% of A and A _also_ overlaps 90% of B." << endl << endl;
    cout << "	-e	Require that the minimum fraction be satisfied for A OR B." << endl;
