struct BedRecord {
    string chrom;
    int start;
    int end;
    vector<string> fields;
    string line;
};

BedRecord parse_line(string line) {
    BedRecord r;
    r.line = line;
    stringstream ss(line);
    string f;
    while (ss >> f) r.fields.push_back(f);
    if (r.fields.size() >= 3) {
        r.chrom = r.fields[0];
        try {
            r.start = stoi(r.fields[1]);
            r.end = stoi(r.fields[2]);
        } catch (...) {
            r.start = -1;
            r.end = -1;
        }
    } else {
        r.start = -1;
        r.end = -1;
    }
    return r;
}

int intersect_main(int argc, char** argv) {
    string a_file, b_file;
    bool wa = false, wb = false, u = false, v = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-a") a_file = argv[++i];
        else if (arg == "-b") b_file = argv[++i];
        else if (arg == "-wa") wa = true;
        else if (arg == "-wb") wb = true;
        else if (arg == "-u") u = true;
        else if (arg == "-v") v = true;
    }
    if (a_file.empty() || b_file.empty()) {
        intersect_help();
        cerr << "***** ERROR: No input file given. Exiting. *****" << endl;
        return 1;
    }

    // Load B
    map<string, vector<BedRecord>> b_data;
    ifstream in_b(b_file);
    string line;
    while (getline(in_b, line)) {
        if (line.empty() || line[0] == '#') continue;
        BedRecord r = parse_line(line);
        if (r.start != -1) b_data[r.chrom].push_back(r);
    }

    // Process A
    ifstream in_a(a_file);
    while (getline(in_a, line)) {
        if (line.empty() || line[0] == '#') continue;
        BedRecord ra = parse_line(line);
        if (ra.start == -1) continue;

        bool found = false;
        if (b_data.count(ra.chrom)) {
            for (const auto& rb : b_data[ra.chrom]) {
                int s = max(ra.start, rb.start);
                int e = min(ra.end, rb.end);
                if (s < e) {
                    found = true;
                    if (u) {
                        break;
                    } else if (v) {
                        // skip
                    } else if (wa && wb) {
                        cout << ra.line << "\t" << rb.line << endl;
                    } else if (wa) {
                        cout << ra.line << endl;
                    } else if (wb) {
                        cout << ra.chrom << "\t" << s << "\t" << e;
                        for (size_t i = 3; i < ra.fields.size(); ++i) cout << "\t" << ra.fields[i];
                        cout << "\t" << rb.line << endl;
                    } else {
                        cout << ra.chrom << "\t" << s << "\t" << e;
                        for (size_t i = 3; i < ra.fields.size(); ++i) cout << "\t" << ra.fields[i];
                        cout << endl;
                    }
                }
            }
        }

        if (u && found) {
            cout << ra.line << endl;
        } else if (v && !found) {
            cout << ra.line << endl;
        }
    }
    return 0;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        print_main_help();
        return 0;
    }
    string cmd = argv[1];
    if (cmd == "--help" || cmd == "-h") {
        print_main_help();
        return 0;
    }
    if (cmd == "--version") {
        cout << "bedtools b2e3657" << endl;
        return 0;
    }
    if (cmd == "intersect") return intersect_main(argc, argv);
    else {
        cerr << "error: unrecognized command: " << cmd << endl << endl;
        return 1;
    }
    return 0;
}
