int intersect_main(int argc, char** argv) {
    string a_file; vector<string> b_files;
    bool wa = false, wb = false, u = false, v = false, c = false, wo = false, wao = false, loj = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-a") a_file = argv[++i];
        else if (arg == "-b") {
            while (i + 1 < argc && argv[i+1][0] != '-') b_files.push_back(argv[++i]);
        }
        else if (arg == "-wa") wa = true;
        else if (arg == "-wb") wb = true;
        else if (arg == "-u") u = true;
        else if (arg == "-v") v = true;
        else if (arg == "-c") c = true;
        else if (arg == "-wo") wo = true;
        else if (arg == "-wao") wao = true;
        else if (arg == "-loj") loj = true;
    }
    if (a_file.empty() || b_files.empty()) return 1;
    map<string, vector<BedRecord>> b_data;
    for (const auto& bf : b_files) {
        ifstream f; istream* in = open_file(bf, f);
        if (!in) continue;
        string line;
        while (getline(*in, line)) {
            if (line.empty() || line[0] == '#') continue;
            BedRecord r = parse_line(line);
            if (r.start != -1) b_data[r.chrom].push_back(r);
        }
    }
    ifstream f_a; istream* in_a = open_file(a_file, f_a);
    if (!in_a) return 1;
    string line;
    while (getline(*in_a, line)) {
        if (line.empty() || line[0] == '#') continue;
        BedRecord ra = parse_line(line);
        if (ra.start == -1) continue;
        int count = 0; bool found = false;
        if (b_data.count(ra.chrom)) {
            for (const auto& rb : b_data[ra.chrom]) {
                int s = max(ra.start, rb.start);
                int e = min(ra.end, rb.end);
                if (s < e) {
                    found = true; count++;
                    if (!u && !v && !c) {
                        if (wa && wb) cout << ra.line << "\t" << rb.line << endl;
                        else if (wa) cout << ra.line << endl;
                        else if (wb) {
                            cout << ra.chrom << "\t" << s << "\t" << e;
                            for (size_t i = 3; i < ra.fields.size(); ++i) cout << "\t" << ra.fields[i];
                            cout << "\t" << rb.line << endl;
                        } else if (wo || wao) cout << ra.line << "\t" << rb.line << "\t" << (e - s) << endl;
                        else {
                            cout << ra.chrom << "\t" << s << "\t" << e;
                            for (size_t i = 3; i < ra.fields.size(); ++i) cout << "\t" << ra.fields[i];
                            cout << endl;
                        }
                    }
                }
            }
        }
        if (u && found) cout << ra.line << endl;
        else if (v && !found) cout << ra.line << endl;
        else if (c) cout << ra.line << "\t" << count << endl;
        else if (loj && !found) cout << ra.line << "\t.\t-1\t-1" << endl;
        else if (wao && !found) cout << ra.line << "\t.\t-1\t-1\t0" << endl;
    }
    return 0;
}

int merge_main(int argc, char** argv) {
    string i_file; int d = 0;
    for (int i = 2; i < argc; ++i) {
        if (string(argv[i]) == "-i") i_file = argv[++i];
        else if (string(argv[i]) == "-d") d = stoi(argv[++i]);
    }
    if (i_file.empty()) return 1;
    ifstream f; istream* in = open_file(i_file, f);
    if (!in) return 1;
    string line, last_chrom = ""; int last_s = -1, last_e = -1;
    while (getline(*in, line)) {
        BedRecord r = parse_line(line); if (r.start == -1) continue;
        if (r.chrom == last_chrom && r.start <= last_e + d) last_e = max(last_e, r.end);
        else {
            if (!last_chrom.empty()) cout << last_chrom << "\t" << last_s << "\t" << last_e << endl;
            last_chrom = r.chrom; last_s = r.start; last_e = r.end;
        }
    }
    if (!last_chrom.empty()) cout << last_chrom << "\t" << last_s << "\t" << last_e << endl;
    return 0;
}

int sort_main(int argc, char** argv) {
    string i_file;
    for (int i = 2; i < argc; ++i) if (string(argv[i]) == "-i") i_file = argv[++i];
    if (i_file.empty()) return 1;
    vector<BedRecord> recs; ifstream f; istream* in = open_file(i_file, f);
    if (!in) return 1;
    string line; while (getline(*in, line)) {
        BedRecord r = parse_line(line); if (r.start != -1) recs.push_back(r);
    }
    sort(recs.begin(), recs.end(), [](const BedRecord& a, const BedRecord& b){
        if (a.chrom != b.chrom) return a.chrom < b.chrom;
        return a.start < b.start;
    });
    for (auto& r : recs) cout << r.line << endl;
    return 0;
}

int subtract_main(int argc, char** argv) {
    string a_file, b_file;
    for (int i = 2; i < argc; ++i) {
        if (string(argv[i]) == "-a") a_file = argv[++i];
        else if (string(argv[i]) == "-b") b_file = argv[++i];
    }
    if (a_file.empty() || b_file.empty()) return 1;
    map<string, vector<BedRecord>> b_data;
    ifstream fb; istream* in_b = open_file(b_file, fb);
    if (!in_b) return 1;
    string line; while (getline(*in_b, line)) {
        BedRecord r = parse_line(line); if (r.start != -1) b_data[r.chrom].push_back(r);
    }
    ifstream fa; istream* in_a = open_file(a_file, fa);
    if (!in_a) return 1;
    while (getline(*in_a, line)) {
        BedRecord ra = parse_line(line); if (ra.start == -1) continue;
        vector<pair<int, int>> parts; parts.push_back({ra.start, ra.end});
        if (b_data.count(ra.chrom)) {
            for (const auto& rb : b_data[ra.chrom]) {
                vector<pair<int, int>> next_parts;
                for (auto& p : parts) {
                    if (rb.start >= p.second || rb.end <= p.first) next_parts.push_back(p);
                    else {
                        if (rb.start > p.first) next_parts.push_back({p.first, rb.start});
                        if (rb.end < p.second) next_parts.push_back({rb.end, p.second});
                    }
                }
                parts = next_parts;
            }
        }
        for (auto& p : parts) {
            cout << ra.chrom << "\t" << p.first << "\t" << p.second;
            for (size_t i = 3; i < ra.fields.size(); ++i) cout << "\t" << ra.fields[i];
            cout << endl;
        }
    }
    return 0;
}

int main(int argc, char* argv[]) {
    if (argc < 2) { print_main_help(); return 0; }
    string cmd = argv[1];
    if (cmd == "--version") { cout << "bedtools b2e3657" << endl; return 0; }
    if (cmd == "intersect") return intersect_main(argc, argv);
    if (cmd == "merge") return merge_main(argc, argv);
    if (cmd == "sort") return sort_main(argc, argv);
    if (cmd == "subtract") return subtract_main(argc, argv);
    cerr << "error: unrecognized command: " << cmd << endl << endl;
    return 1;
}
